// Arma la alerta de error: que flujo, que paso, que error, cuando y que revisar.
const d = $input.first().json;
const ex = d.execution || {};
const wf = d.workflow || {};
const trg = d.trigger || {};
const err = ex.error || trg.error || {};
// Los errores de un nodo Code (throw new Error) llegan partidos en el primer ':' (description = lo de antes, message = lo de despues). Se vuelven a juntar.
const esDeCodigo = err.name === 'WrappedExecutionError' || /throw-execution-error/.test(String(err.stack || ''));
let mensaje = String(err.message || err.description || 'Sin mensaje de error');
let detalle = String(err.description || '');
if (esDeCodigo && err.description && err.message) {
  const antes = String(err.description);
  const despues = String(err.message);
  const sep = /[0-9]$/.test(antes) && /^[0-9]/.test(despues) ? ':' : ': ';
  mensaje = antes + sep + despues;
  detalle = '';
}
const nodo = (err.node && err.node.name) || ex.lastNodeExecuted || (trg.error ? 'disparador del flujo' : 'desconocido');
const flujo = wf.name || 'desconocido';
const hora = $now.setZone('America/Montevideo').toFormat('dd/MM/yyyy HH:mm');
const link = ex.url || (wf.id ? 'https://tu-n8n.ejemplo.com/workflow/' + wf.id : '');
const t = (mensaje + ' ' + detalle).toLowerCase();
let pista;
if (/401|403|unauthori|forbidden|invalid[_ ]?(grant|token|key|api)|expired|revoked|key not found|credential/.test(t)) {
  pista = 'Parece una credencial vencida o revocada. Entra a n8n > Credentials, busca la del servicio de ese paso y reconectala.';
} else if (/429|rate limit|too many|quota/.test(t)) {
  pista = 'El servicio esta frenando pedidos por exceso (limite o cuota). Suele pasar solo; si se repite, revisa la cuota del servicio.';
} else if (/timeout|timed out|econnreset|econnrefused|enotfound|socket hang up|502|503|504|service unavailable/.test(t)) {
  pista = 'El servicio externo no respondio (caido o lento). Suele ser pasajero; si se repite, revisa si ese servicio tiene problemas.';
} else if (/404|not found|does not exist/.test(t)) {
  pista = 'No se encontro algo que el flujo buscaba (un ID, una lista, una hoja o un link). Revisa que siga existiendo.';
} else {
  pista = 'Abri la ejecucion con el boton de abajo y mira el paso marcado en rojo.';
}
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fila = (k, v) => '<tr><td style="padding:6px 14px 6px 0;color:#666;vertical-align:top;white-space:nowrap">' + k + '</td><td style="padding:6px 0;color:#111">' + v + '</td></tr>';
let filas = fila('Flujo', esc(flujo)) + fila('Paso', esc(nodo)) + fila('Error', esc(mensaje.slice(0, 500)));
if (detalle && detalle !== mensaje) filas += fila('Detalle', esc(detalle.slice(0, 500)));
filas += fila('Hora (Uruguay)', esc(hora)) + fila('Modo', esc(ex.mode || '-'));
let html = '<div style="font-family:Arial,sans-serif;font-size:15px;line-height:22px;max-width:600px">';
html += '<p style="margin:0 0 12px 0;font-size:18px"><strong>Fallo el flujo ' + esc(flujo) + '</strong></p>';
html += '<table style="border-collapse:collapse">' + filas + '</table>';
html += '<p style="margin:16px 0 8px 0"><strong>Que revisar:</strong> ' + esc(pista) + '</p>';
if (link) html += '<p style="margin:18px 0"><a href="' + esc(link) + '" style="background:#111;color:#fff;padding:10px 16px;border-radius:6px;text-decoration:none">Ver la ejecucion en n8n</a></p>';
html += '</div>';
// Clave para no repetir la misma alerta: flujo + paso + error.
// Se sacan numeros largos e IDs (cambian en cada corrida) para que la misma falla de la misma clave.
const normalizar = (s) => String(s).toLowerCase().replace(/\b[0-9a-f-]{16,}\b/g, '#').replace(/\d{4,}/g, '#').replace(/\s+/g, ' ').trim();
const clave = (normalizar(flujo) + ' | ' + normalizar(nodo) + ' | ' + normalizar(mensaje)).slice(0, 400);
return [{ json: { asunto: 'Fallo ' + flujo + ' (paso: ' + nodo + ')', html, flujo, nodo, mensaje, hora, pista, link, clave } }];

// Decide si la alerta sale o se suprime.
// Misma falla (flujo + paso + error) ya avisada hace menos de 6 h = no se reenvia, solo se cuenta.
// Una falla distinta sale siempre al instante.
const VENTANA_HORAS = 6;
const a = $('armar_alerta').first().json;
const items = $input.all().map(i => i.json || {});
// Si no se pudo leer la tabla, la alerta sale igual (mejor repetida que perdida).
const busquedaFallo = items.some(f => f.error && !f.clave);
const filas = items.filter(f => f.clave === a.clave);
filas.sort((x, y) => new Date(y.ultima_enviada || 0).getTime() - new Date(x.ultima_enviada || 0).getTime());
const previa = filas[0];
const ultima = previa && previa.ultima_enviada ? new Date(previa.ultima_enviada).getTime() : NaN;
const dentroDeVentana = !isNaN(ultima) && (Date.now() - ultima) < VENTANA_HORAS * 3600 * 1000;

if (previa && dentroDeVentana) {
  return [{ json: { enviar: false, clave: a.clave, suprimidas: (Number(previa.suprimidas) || 0) + 1 } }];
}

const repetidas = previa ? (Number(previa.suprimidas) || 0) : 0;
let asunto = a.asunto;
let extra = '';
if (repetidas > 0) {
  const desde = DateTime.fromMillis(ultima).setZone('America/Montevideo').toFormat('dd/MM HH:mm');
  const veces = repetidas + (repetidas === 1 ? ' vez' : ' veces');
  asunto += ' - se repitio ' + veces;
  extra += '<p style="margin:16px 0 8px 0;padding:10px 12px;background:#fff4e5;border-radius:6px"><strong>Ojo:</strong> este mismo error se repitio ' + veces + ' desde la alerta anterior (' + desde + ') y volvio a pasar ahora. Esas no te las mande para no llenarte la bandeja.</p>';
}
if (busquedaFallo) {
  extra += '<p style="margin:8px 0;color:#a00">No pude revisar la tabla alertas_enviadas, asi que esta alerta puede ser repetida.</p>';
}
extra += '<p style="margin:16px 0 0 0;color:#666;font-size:13px">Si este mismo error se repite, no te mando otra alerta igual por 6 horas; en la proxima te digo cuantas veces paso. Un error distinto te llega al instante.</p>';
const html = a.html.replace(/<\/div>\s*$/, extra + '</div>');
return [{ json: { enviar: true, asunto, html, clave: a.clave, flujo: a.flujo, nodo: a.nodo, mensaje: String(a.mensaje).slice(0, 500) } }];
